function toInt(x: unknown): bigint | null {
  if (typeof x === "bigint") {
    return x;
  }
  if (typeof x === "number" && Number.isInteger(x)) {
    return BigInt(x);
  }
  const obj = x as { value?: unknown; toBigInt?: () => bigint } | null;
  if (obj !== null && typeof obj === "object") {
    if (typeof obj.toBigInt === "function") {
      return obj.toBigInt();
    }
    if (obj.value !== undefined) {
      return toInt(obj.value);
    }
  }
  return null;
}

